import {
  createHash,
  createPublicKey,
  diffieHellman,
  generateKeyPairSync,
  hkdfSync,
  KeyObject,
  randomBytes
} from 'crypto'
import { encrypt, decrypt } from './db'

/**
 * Key material for passwordless cloud sync. Must stay byte-compatible with the mobile
 * app's mobile/src/crypto/cloudKeys.ts — a key wrapped on one must unwrap on the other.
 *
 *  Data Key (DK)    32 random bytes, generated by the first device. Encrypts every synced
 *                   record and file (db.ts's AES-256-GCM envelope). Never leaves a device
 *                   unwrapped.
 *  Recovery Key     20 random bytes, shown to the user once as 32 Crockford-base32 chars.
 *                   HKDF → wrap key → seals DK; the server stores only that sealed copy.
 *                   160 random bits, so unlike a password it needs no slow KDF to resist
 *                   guessing.
 *  Key proof        HKDF(DK, 'artha-key-proof'). Sent to prove "this device holds DK"
 *                   (server keeps only its sha256). One-way, so it reveals nothing about DK.
 *  Device link      New device: X25519 keypair. Approving device: ephemeral X25519 keypair,
 *                   ECDH → HKDF(salt = ephPub ‖ devicePub) → seals DK to the new device.
 */

const EMPTY = Buffer.alloc(0)

function hkdf(ikm: Buffer, info: string, salt: Buffer = EMPTY): Buffer {
  return Buffer.from(hkdfSync('sha256', ikm, salt, info, 32))
}

export function generateDataKey(): Buffer {
  return randomBytes(32)
}

export function keyProof(dataKey: Buffer): Buffer {
  return hkdf(dataKey, 'artha-key-proof')
}

export function keyProofHash(dataKey: Buffer): string {
  return createHash('sha256').update(keyProof(dataKey)).digest('hex')
}

// ── Recovery Key ──────────────────────────────────────────────────────────────

// Crockford base32: no I, L, O or U, so it survives being read aloud or handwritten.
const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ'
const RECOVERY_KEY_BYTES = 20 // → exactly 32 characters

export function generateRecoveryKey(): Buffer {
  return randomBytes(RECOVERY_KEY_BYTES)
}

/** "7KQ2-M9XD-…" — 8 groups of 4. */
export function formatRecoveryKey(bytes: Buffer): string {
  let bits = 0
  let value = 0
  let out = ''
  for (const byte of bytes) {
    value = (value << 8) | byte
    bits += 8
    while (bits >= 5) {
      out += ALPHABET[(value >>> (bits - 5)) & 31]
      bits -= 5
    }
  }
  if (bits > 0) out += ALPHABET[(value << (5 - bits)) & 31]
  return out.match(/.{1,4}/g)!.join('-')
}

/** Accepts any spacing/dashes/case and the usual look-alikes (O→0, I/L→1). */
export function parseRecoveryKey(text: string): Buffer {
  const clean = text
    .toUpperCase()
    .replace(/[\s-]/g, '')
    .replace(/O/g, '0')
    .replace(/[IL]/g, '1')
  if (clean.length !== 32 || [...clean].some((c) => !ALPHABET.includes(c))) {
    throw new Error("That doesn't look like a recovery key — it should be 32 letters and numbers")
  }
  let bits = 0
  let value = 0
  const out: number[] = []
  for (const c of clean) {
    value = (value << 5) | ALPHABET.indexOf(c)
    bits += 5
    if (bits >= 8) {
      out.push((value >>> (bits - 8)) & 255)
      bits -= 8
    }
  }
  return Buffer.from(out)
}

export function wrapWithRecoveryKey(dataKey: Buffer, recoveryKey: Buffer): string {
  return encrypt(dataKey, hkdf(recoveryKey, 'artha-recovery-wrap')).toString('base64')
}

export function unwrapWithRecoveryKey(wrapped: string, recoveryKey: Buffer): Buffer {
  try {
    return Buffer.from(decrypt(Buffer.from(wrapped, 'base64'), hkdf(recoveryKey, 'artha-recovery-wrap')))
  } catch {
    throw new Error("That recovery key doesn't match this account")
  }
}

// ── Device link (X25519) ──────────────────────────────────────────────────────

function rawPublicKey(key: KeyObject): Buffer {
  const jwk = key.export({ format: 'jwk' }) as { x: string }
  return Buffer.from(jwk.x, 'base64url')
}

function importPublicKey(raw: Buffer): KeyObject {
  return createPublicKey({ key: { kty: 'OKP', crv: 'X25519', x: raw.toString('base64url') }, format: 'jwk' })
}

export interface LinkKeyPair {
  privateKey: KeyObject
  publicKey: Buffer // raw 32 bytes
}

export function generateLinkKeyPair(): LinkKeyPair {
  const { privateKey, publicKey } = generateKeyPairSync('x25519')
  return { privateKey, publicKey: rawPublicKey(publicKey) }
}

function linkWrapKey(shared: Buffer, ephemeralPublic: Buffer, devicePublic: Buffer): Buffer {
  return hkdf(shared, 'artha-device-link', Buffer.concat([ephemeralPublic, devicePublic]))
}

/** Approving device: seals the Data Key to the new device's public key. */
export function sealForDevice(dataKey: Buffer, devicePublicB64: string): { ephemeralPublicKey: string; wrappedKey: string } {
  const devicePublic = Buffer.from(devicePublicB64, 'base64')
  const eph = generateLinkKeyPair()
  const shared = diffieHellman({ privateKey: eph.privateKey, publicKey: importPublicKey(devicePublic) })
  const wrapped = encrypt(dataKey, linkWrapKey(shared, eph.publicKey, devicePublic))
  return { ephemeralPublicKey: eph.publicKey.toString('base64'), wrappedKey: wrapped.toString('base64') }
}

/** New device: opens what the approving device sealed. */
export function openFromDevice(pair: LinkKeyPair, ephemeralPublicB64: string, wrappedB64: string): Buffer {
  const ephemeralPublic = Buffer.from(ephemeralPublicB64, 'base64')
  const shared = diffieHellman({ privateKey: pair.privateKey, publicKey: importPublicKey(ephemeralPublic) })
  return Buffer.from(decrypt(Buffer.from(wrappedB64, 'base64'), linkWrapKey(shared, ephemeralPublic, pair.publicKey)))
}

/** Six digits both devices derive from the requesting device's public key — shown on
 * each screen so the user can confirm they're approving *their* device, not a key a
 * compromised server swapped in. */
export function linkCode(publicKeyB64: string): string {
  const digest = createHash('sha256').update(Buffer.from(publicKeyB64, 'base64')).digest()
  const n = digest.readUInt32BE(0) % 1_000_000
  const s = n.toString().padStart(6, '0')
  return `${s.slice(0, 3)} ${s.slice(3)}`
}
